import sys; sys.path.insert(0,'/home/claude/scripts')
from facts_lib import save
N="تعليمات منح شهادة الاختصاص العالي في طب وجراحة الأسنان"
F=[]
def r(c,a,q1,q2,q3): F.append(("rule",[1],c,a,q1,q2,q3))
r("المادة 1","تسمى هذه التعليمات «تعليمات منح شهادة الاختصاص العالي في طب وجراحة الأسنان بجامعة العلوم والتكنولوجيا الأردنية»، ويعمل بها من تاريخ صدور قرار مجلس العمداء بذلك وتسري على جميع الطلبة على مقعد الدراسة حين صدور القرار وعلى المقبولين بعد صدوره.","على من تسري تعليمات الاختصاص العالي في طب وجراحة الأسنان؟","ما اسم التعليمات ومتى يعمل بها؟","على مين بتنطبق تعليمات الاختصاص العالي بطب الأسنان؟")
r("المادة 2","السنة الدراسية في برنامج الاختصاص العالي في طب وجراحة الأسنان اثنا عشر شهراً تشمل مدة الامتحانات، والعيادات هي عيادات طب الأسنان التعليمية والتخصصية التابعة للكلية أو المرتبطة بالجامعة باتفاقيات معتمدة، والمستشفى هو مستشفى الملك المؤسس عبد الله الجامعي أو المستشفيات والمراكز المرتبطة بالجامعة باتفاقيات معتمدة لأغراض التدريب.","كم مدة السنة الدراسية في الاختصاص العالي في طب وجراحة الأسنان؟","ماذا تعني العيادات والمستشفى في تعليمات الاختصاص العالي بطب الأسنان؟","كم شهر السنة الدراسية بالاختصاص العالي؟")
r("المادة 3","تقدم طلبات الالتحاق ببرنامج الاختصاص العالي في طب وجراحة الأسنان إلكترونياً إلى عمادة كلية الدراسات العليا مباشرة حسب نموذج خاص، ولا يبت في أي طلب إلا إذا استوفى جميع الأوراق الثبوتية، ثم يحول إلى الكلية والقسم للتنسيب بأسماء المرشحين حسب الشواغر إلى عمادة الدراسات العليا لإعلان القوائم.","كيف تقدم طلبات الالتحاق بالاختصاص العالي في طب وجراحة الأسنان؟","هل يبت في الطلب إذا كانت الأوراق الثبوتية ناقصة؟","كيف بقدم طلب للاختصاص العالي بطب الأسنان؟")
r("المادة 4 (تفصيل)","من شروط القبول أيضاً: أن يكون الطالب قد اجتاز الامتحان الإجمالي المقرر لأطباء الأسنان الأردنيين من خريجي الجامعات غير الأردنية، وأن يكون مسجلاً في نقابة أطباء الأسنان الأردنية تسجيلاً دائماً للأردنيين أو مؤقتاً لغير الأردنيين، ومرخصاً من وزارة الصحة لمزاولة المهنة ترخيصاً دائماً للأردنيين أو مؤقتاً لغير الأردنيين، وأن يكون قد أتم فترة الامتياز كما يحددها المجلس الطبي الأردني أو ما يعادلها من خبرة لغير الأردنيين.","هل يختلف التسجيل في النقابة والترخيص للأردنيين وغير الأردنيين في الاختصاص العالي بطب الأسنان؟","هل يشترط امتحان إجمالي لخريجي الجامعات غير الأردنية في الاختصاص العالي بطب الأسنان؟","كيف تحسب فترة الامتياز لغير الأردني؟")
r("المادة 5","يحدد مجلس العمداء أعداد الطلبة المقبولين في كل تخصص بناءً على تنسيب المجلس وحسب توصية لجنتي القسم والكلية مع مراعاة الشواغر الناتجة عن انسحاب أو فصل أي طالب. ويتم قبول الطالب بقرار من العميد بناءً على توصية لجنة القسم وتنسيب لجنة الكلية. ويتعهد الطالب المقبول خطياً بأن يكون متفرغاً لدراسته وتدريبه، وعليه التسجيل ودفع الرسوم عند بدء كل سنة دراسية.","من يحدد أعداد المقبولين ومن يقرر قبول الطالب في الاختصاص العالي في طب وجراحة الأسنان؟","هل يشترط التفرغ للدراسة والتدريب في الاختصاص العالي بطب الأسنان؟","متى يسجل الطالب ويدفع الرسوم في الاختصاص العالي؟")
r("المادة 6 (أ، ب)","يقترح مجلس القسم الخطة الدراسية وتقرها مجلس العمداء بتوصية لجنة الخطة الدراسية في الجامعة. ويشترط أن تحتوي الخطة على مشروع بحث علمي في التخصص يعده الطالب تحت إشراف أحد أعضاء الهيئة التدريسية في القسم، ويعين مشرف البحث بقرار من رئيس القسم وبتوصية لجنة الدراسات العليا في القسم.","هل تتضمن خطة الاختصاص العالي في طب وجراحة الأسنان مشروع بحث؟","من يعين مشرف البحث في الاختصاص العالي بطب الأسنان؟","من يقر الخطة الدراسية للاختصاص العالي؟")
r("المادة 6 (د، هـ)","الحد الأدنى لسنوات الدراسة والتدريب هو عدد السنوات المقررة في الخطة الدراسية لكل تخصص، والحد الأعلى هو عدد سنوات الخطة مضافاً إليها سنتان دراسيتان فقط شريطة أن تكون إحداهما السنة الأخيرة المعادة.","ما الحد الأدنى والأعلى لسنوات الدراسة في الاختصاص العالي في طب وجراحة الأسنان؟","كم سنة يمكن إضافتها على مدة الخطة في الاختصاص العالي بطب الأسنان؟","كم سنة بحد أقصى بقدر أدرس بالاختصاص العالي؟")
r("المادة 6 (و، ز)","يتدرب الطالب في المستشفى أو العيادات طيلة التحاقه بالبرنامج، ويسمح لطالب السنة الثانية فما فوق بقضاء فترة لا تزيد عن ستة أشهر خلال البرنامج كاملاً بموافقة المجلس: في مؤسسات صحية داخل الأردن تقدم خدمات غير متوفرة لمدة لا تزيد عن ثلاثة أشهر، أو خارج الأردن (أمريكا، كندا، أستراليا، الدول الأوروبية، أو مراكز عربية معتمدة لدى الجامعات الأمريكية) لمدة لا تزيد عن ثلاثة أشهر في أي سنة. ويقدم طلب التدريب قبل بدايته بشهرين على الأقل مشفوعاً بقبول رسمي من الجهة موضحاً آلية الدوام.","كم مدة التدريب الخارجي المسموحة في الاختصاص العالي في طب وجراحة الأسنان وأين؟","قبل كم شهر يقدم طلب التدريب خارج الجامعة؟","بقدر أتدرب برا الأردن بالاختصاص العالي؟")
r("المادة 7 (أ، ب)","يعين رئيس القسم من أعضاء هيئة التدريس لكل تخصص مشرفاً لطلبة الاختصاص العالي يوجههم في سير دراستهم. وتشترط المواظبة في جميع السنوات، ويسجل المشرف على التدريب الحضور والغياب على كشوف خاصة ويسلمها لرئيس القسم في نهاية كل سنة قبل الامتحان النهائي.","من يوجه طلبة الاختصاص العالي في طب وجراحة الأسنان ومن يسجل الحضور والغياب؟","متى يسلم المشرف كشوف الحضور والغياب لرئيس القسم؟","مين بسجل غيابي بالاختصاص العالي؟")
r("المادة 7 (ج، و)","تشمل الأسابيع الخمسة المسموح بالتغيب فيها في السنة الدراسية الإجازة السنوية الممنوحة من المستشفى أو العيادات. ويشترط في العذر المرضي شهادة صادرة عن المركز الصحي في الجامعة أو مستشفى الملك المؤسس عبد الله الجامعي ومعتمدة من اللجان الطبية، ويقدمها الطالب إلى عميد الكلية خلال أسبوعين من تاريخ الانقطاع، وفي الحالات القاهرة يقدم ما يثبت العذر خلال أسبوعين من زوال أسباب الغياب.","خلال كم أسبوعاً يقدم الطالب الشهادة المرضية في الاختصاص العالي في طب وجراحة الأسنان؟","هل تدخل الإجازة السنوية ضمن أسابيع الغياب الخمسة؟","من أين لازم تكون الشهادة المرضية؟")
r("المادة 8 (أ)","إذا رغب طالب الاختصاص العالي في الانسحاب من الجامعة فعليه التقدم بطلب على النموذج المعد إلى وحدة القبول والتسجيل، وتثبت له في سجله ملاحظة (منسحب من الجامعة) ويفقد حقه في المقعد، ويبلغ العميد وعميد الكلية ورئيس القسم.","كيف ينسحب طالب الاختصاص العالي في طب وجراحة الأسنان من الجامعة وماذا يثبت في سجله؟","هل يفقد مقعده عند الانسحاب من الجامعة؟","بدي أنسحب من الاختصاص العالي، كيف؟")
r("المادة 8 (ج)","يجوز للطالب الذي أنهى السنة الأولى بنجاح الانسحاب من أي من السنوات التالية بعد بدايتها وقبل عقد الامتحان النهائي للسنة بأسبوعين على الأقل بقرار من العميد بناءً على تنسيب لجنة الكلية وتوصية لجنة القسم، ويعتبر الطالب مؤجلاً للسنة المعنية، ويبلغ العميد القرار إلى الطالب وعميد الكلية والمسجل العام.","متى يجوز الانسحاب من سنة دراسية بعد السنة الأولى في الاختصاص العالي في طب وجراحة الأسنان؟","ماذا يعتبر الطالب الذي ينسحب من سنة دراسية بعد الأولى؟","قديش قبل النهائي بقدر أنسحب من السنة؟")
r("المادة 9 (أ، ب، ج)","يشترط لتأجيل الدراسة أن يكون الطالب قد أنهى السنة السابقة بنجاح بعذر قهري يقبله العميد بتنسيب لجنتي القسم والكلية، قبل بداية السنة المراد تأجيلها، ولا يجوز تأجيل السنة الأولى. وللطلبة الذين غابوا أكثر من عشرة أسابيع (المادة 7/ز) يسمح بالتأجيل لمدة عامين كحد أقصى. ويقدم طلب التأجيل إلكترونياً على النموذج المعتمد من كلية الدراسات العليا ويصدر القرار من العميد.","كم سنة يسمح بتأجيلها لمن غاب أكثر من عشرة أسابيع في الاختصاص العالي بطب الأسنان؟","كيف يقدم طلب التأجيل في الاختصاص العالي بطب الأسنان؟","بقدر أأجل السنة الأولى؟")
r("المادة 9 (د-و)","لا تحسب مدة التأجيل من الحد الأعلى لسنوات الدراسة أو لغاية إزالة أسباب الوضع تحت المراقبة. ولا يجوز لصاحب ملاحظة (غير مكتمل) تأجيل دراسته إلا بعد إزالتها وإلا ترصد له العلامة المستحقة من الأعمال الفصلية. وتعتبر دراسة الطالب الذي غاب أكثر من عشرة أسابيع مؤجلة حكماً ويبلغ العميد المسجل العام.","ماذا يعني تأجيل الدراسة حكماً في الاختصاص العالي في طب وجراحة الأسنان؟","هل أقدر أأجل وعندي غير مكتمل بالاختصاص العالي؟","بتنحسب مدة التأجيل من الحد الأعلى؟")
r("المادة 10","إذا كان قبول الطالب في الاختصاص العالي على نفقة المستشفى فإن الموافقة على انسحابه أو تأجيله لا تلزم المستشفى عند عودته بدفع الرسوم الجامعية وراتب شهري له، وإنما يخضع ذلك لتوافر الشواغر والمخصصات في موازنة المستشفى.","هل تلتزم المستشفى بدفع الرسوم والراتب عند عودة الطالب بعد التأجيل في الاختصاص العالي؟","ماذا لو كان قبول الطالب على نفقة المستشفى وأجل دراسته؟","إذا أجلت وكنت على نفقة المستشفى، بيرجعوا يدفعوا لي؟")
r("المادة 11 (ب)","يجوز للطالب الذي فقد مقعده التقدم بطلب جديد للقبول في نفس التخصص شريطة ألا يكون تحت المراقبة عند فقدانه مقعده، وفي حال قبوله يتقدم بطلب لاحتساب المساقات التي درسها وفق الخطة النافذة بقرار من العميد، وتحسم مدة دراسته المحتسبة من الحد الأعلى لمدة الدراسة.","هل يجوز لمن فقد مقعده في الاختصاص العالي بطب الأسنان التقدم بطلب جديد؟","من لا يحق له إعادة التقدم بعد فقدان المقعد؟","فقدت مقعدي وكنت تحت المراقبة، بقدر أرجع؟")
r("المادة 12 (أ/2، ب، ج)","يوضع الطالب بسبب تقرير المشرف السنوي تحت المراقبة بموافقة العميد بتنسيب لجنة الكلية وتوصية لجنة القسم بعد اطلاعها على التقرير. وعليه إزالة أسباب المراقبة بناءً على نتائج السنة التالية: إعادة آخر سنة إذا وضع تحت المراقبة في سنتين متتاليتين بسبب انخفاض المعدل السنوي عن 3 بنتيجة ناجح (مرة واحدة فقط) أو إعادة السنة التي رسب بها (مرة واحدة فقط) واجتيازها بمعدل سنوي لا يقل عن 3، ويسمح للراسب في السنة الأخيرة بإعادتها مرة إضافية، ولا يزيد عدد السنوات المعادة عن سنة واحدة عدا الأخيرة.","كيف يزيل طالب الاختصاص العالي في طب وجراحة الأسنان وضع المراقبة؟","كم سنة يمكن إعادتها في الاختصاص العالي بطب الأسنان؟","رسبت بالسنة الأخيرة، بقدر أعيدها؟")
r("المادة 13 (أ) تفصيل","يفصل الطالب كذلك إذا لم يستطع رفع معدله العام في نهاية السنة الأخيرة المعادة إلى 3، أو ارتكب مخالفة توجب فصله حسب أنظمة الجامعة. وتصدر قرارات الفصل من مجلس العمداء بناءً على تنسيب من العميد، وتشعر وحدة القبول والتسجيل الطالب إلكترونياً على آخر عنوان له لدى الجامعة.","من يصدر قرار الفصل في الاختصاص العالي في طب وجراحة الأسنان وكيف يبلغ الطالب؟","هل يفصل الطالب إذا لم يرفع معدله العام إلى 3 في السنة الأخيرة المعادة؟","كيف بعرف إنو انفصلت؟")
r("المادة 14 (أ/1-6)","شروط انتقال الطالب من برنامج اختصاص عالي في جامعة أخرى أو مؤسسة طبية معتمدة: توفر شاغر في التخصص، وإتمام السنة الأولى بنجاح، وتحقق شروط القبول، وقضاء ثلاث سنوات في جراحة الفم والوجه والفكين وسنتين في باقي التخصصات. يقبل في السنة الأولى من أنهى الأولى، ويقبل في السنة الثانية من أنهى الثانية وما بعدها بغض النظر عن عدد السنوات السابقة، ولا تدخل علامات السنوات المحتسبة من خارج الجامعة في المعدل العام وتحسب ضمن الحد الأعلى للسنوات.","في أي سنة يقبل المنتقل من جامعة أخرى في الاختصاص العالي في طب وجراحة الأسنان؟","هل تدخل علامات السنوات المحتسبة من خارج الجامعة في المعدل العام؟","كم سنة لازم أقضي بالجامعة إذا انتقلت من جامعة ثانية؟")
r("المادة 15 (أ، ب، د)","تحسب العلامة النهائية لكل مساق أو سنة دراسية من مئة لأقرب عدد صحيح، وهي مجموع علامات الامتحان النهائي وأعمال السنة. ويكون الامتحان النهائي في نهاية السنة الأخيرة شاملاً لمحتوى البرنامج في السنوات السابقة.","هل الامتحان النهائي في السنة الأخيرة شامل للسنوات السابقة في الاختصاص العالي بطب الأسنان؟","كيف تحسب العلامة النهائية للسنة في الاختصاص العالي بطب الأسنان؟","النهائي بالسنة الأخيرة بشمل كل البرنامج؟")
r("المادة 15 (ج/1/II)","يشمل التقييم المهني (10% من علامة المساق) الرعاية الطبية ومتابعة المريض والتوثيق، وفعاليات التعليم الطبي في القسم والمستشفى.","ماذا يشمل التقييم المهني في الاختصاص العالي في طب وجراحة الأسنان وكم نسبته؟","كم نسبة التقييم الأكاديمي والمهني في علامة السنة؟","شو بدخل بالتقييم المهني؟")
r("المادة 15 (و، ز)","إذا تغيب الطالب عن الامتحان النهائي بعذر مرضي أو قهري يقبله عميد الكلية تسجل له ملاحظة (غير مكتمل) ويعقد له امتحان تكميلي بالتنسيق بين رئيس القسم والمشرف على الطالب خلال مدة أقصاها نهاية الأسبوع الأول من بدء السنة الدراسية التالية. وإذا تغيب دون عذر يقبله العميد يوضع له الحد الأدنى للعلامة.","متى يعقد الامتحان التكميلي في الاختصاص العالي في طب وجراحة الأسنان؟","ماذا يحدث لمن تغيب عن الامتحان النهائي بدون عذر؟","غبت عن النهائي بعذر، متى بقدم التكميلي؟")
r("المادة 16 (أ، ب، ج، د)","المعدل السنوي هو معدل النقاط المكافئة للعلامات النهائية في نهاية السنة، والمعدل العام هو معدل جميع المعدلات السنوية، ويحسبان من 4 نقاط. وفي حال إعادة السنة يدخل المعدل السنوي للسنة المعادة في حساب المعدل العام. ويسمح بإعادة السنة الأخيرة إذا قل المعدل العام عن 3 حتى لو كان تحت المراقبة.","كيف يحسب المعدل العام في الاختصاص العالي في طب وجراحة الأسنان؟","هل يدخل معدل السنة المعادة في المعدل العام؟","من كم نقطة بيحسب المعدل بالاختصاص العالي؟")
r("المادة 17 (أ) تفصيل","من متطلبات الحصول على شهادة الاختصاص العالي في طب وجراحة الأسنان: النجاح في جميع السنوات حسب الخطة المعتمدة، وإتمام المدة المقررة، والنجاح في الامتحان السنوي لكل سنة، ومعدل عام لا يقل عن 3، واستكمال البحث السريري وإقراره من مجلس القسم، واستكمال متطلبات التدريب حسب Logbook.","ما دور Logbook في التخرج من الاختصاص العالي في طب وجراحة الأسنان؟","من يقر البحث السريري في الاختصاص العالي بطب الأسنان؟","شو لازم أخلص عشان أتخرج من الاختصاص العالي؟")
r("المادة 18","تمنح شهادة الاختصاص العالي بعد استيفاء جميع متطلبات التخرج بقرار من مجلس العمداء بناءً على تنسيب المجلس وبتوصية لجنتي القسم والكلية.","من يمنح شهادة الاختصاص العالي في طب وجراحة الأسنان؟","بقرار من أي جهة تمنح الشهادة؟","مين بمنح شهادة الاختصاص العالي؟")
r("المادة 19","تتولى لجنة الكلية بالإضافة إلى صلاحياتها في تعليمات كلية الدراسات العليا: التنسيق بين الأقسام المختلفة في الكلية وكلية الطب فيما يتعلق بالبرنامج، وآلية توزيع وتدريب الطلبة في الأقسام المختلفة في الكلية وكلية الطب، وأية أمور أخرى يفوضها بها المجلس.","ما صلاحيات لجنة الكلية في الاختصاص العالي في طب وجراحة الأسنان؟","من ينسق مع كلية الطب بخصوص برنامج الاختصاص العالي؟","شو دور لجنة الكلية بتوزيع الطلبة على الأقسام؟")
r("المادة 20 و21","يبت مجلس العمداء في الحالات التي لم يرد عليها نص أو الإشكاليات التي تنشأ عن تطبيق هذه التعليمات، ورئيس الجامعة والعميد وعميد الكلية والمسجل العام مسؤولون عن تطبيقها.","من يبت في الإشكاليات الناشئة عن تطبيق تعليمات الاختصاص العالي في طب وجراحة الأسنان؟","من المسؤول عن تطبيق تعليمات الاختصاص العالي في طب وجراحة الأسنان؟","مين بحل المشاكل اللي بتصير بتطبيق التعليمات؟")
